/**
 * Validates an object key before it reaches Supabase Storage. Keys are always
 * generated by the API (never taken verbatim from a client), but this guard makes
 * path traversal and malformed keys impossible regardless of caller.
 */
const SEGMENT = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

export class InvalidObjectPathError extends Error {
  constructor(path: string) {
    super(`Invalid storage object path: ${JSON.stringify(path)}`);
    this.name = 'InvalidObjectPathError';
  }
}

export function assertSafeObjectPath(path: string): string {
  if (path.length === 0 || path.length > 512) throw new InvalidObjectPathError(path);
  const segments = path.split('/');
  for (const segment of segments) {
    if (!SEGMENT.test(segment) || segment === '.' || segment.includes('..')) {
      throw new InvalidObjectPathError(path);
    }
  }
  return path;
}
